// Every entry states a cause, a controlled experiment and an explicit expected observation.
const p=(es,en)=>({es,en});
export const foundations={};
function add(id,idea,action,observe,real,controls,kind){foundations[id]={idea:p(...idea),action:p(...action),observe:p(...observe),real:p(...real),controls,kind};}
const c=(es,en,min,max,step,value)=>({label:p(es,en),min,max,step,value});
add('torque',['Una fuerza hace girar mejor cuando empuja lejos del eje y perpendicular al brazo.','A force turns a shaft more effectively when it pushes farther from the axis and perpendicular to the arm.'],['Duplica el brazo y luego cambia el ángulo de 90° a 0°.','Double the arm, then change the angle from 90° to 0°.'],['El par se duplica con el brazo; cae a cero cuando empujas hacia el eje. La flecha muestra la dirección de la fuerza.','Torque doubles with the arm; it falls to zero when you push toward the shaft. The arrow shows force direction.'],['Una llave larga reduce la fuerza necesaria para el mismo par. No cambia el par de apriete especificado.','A long wrench reduces the force needed for the same torque. It does not change the specified tightening torque.'],[c('Fuerza · N','Force · N',10,200,10,100),c('Brazo · m','Arm · m',.1,.5,.05,.25),c('Ángulo · °','Angle · °',0,90,5,90)],'lever');
add('fourstroke',['El pistón va y vuelve; la biela convierte ese movimiento en giro. Solo una de las cuatro carreras recibe trabajo de los gases.','The piston moves back and forth; the rod converts that motion into rotation. Only one of four strokes receives work from the gases.'],['Pausa. Recorre un ciclo y busca las carreras con válvulas cerradas.','Pause. Scrub one cycle and find the strokes with both valves closed.'],['Compresión y expansión tienen válvulas cerradas, pero el pistón cambia de sentido. Dos vueltas de cigüeñal completan el ciclo.','Compression and expansion have closed valves, but the piston changes direction. Two crank revolutions complete the cycle.'],['El volante almacena energía de giro para atravesar carreras que consumen trabajo.','The flywheel stores rotational energy to carry the engine through strokes that consume work.'],[c('Régimen · rpm','Speed · rpm',300,2400,100,1200)],'engine');
add('transmission',['Un diente empuja al siguiente: una rueda con más dientes necesita más tiempo para completar una vuelta.','One tooth pushes the next: a wheel with more teeth takes longer to complete a revolution.'],['Cambia la salida de 18 a 36 dientes y sigue las marcas blancas.','Change the output from 18 to 36 teeth and follow the white marks.'],['La salida gira a la mitad y ofrece el doble de par ideal. La potencia no se duplica.','The output turns at half speed and offers twice the ideal torque. Power does not double.'],['Primera facilita arrancar una carga; una relación larga favorece velocidad con menos par de salida.','First gear helps start a load; a taller gear favours speed with less output torque.'],[c('Dientes de salida','Output teeth',18,54,18,36),c('Par entrada · N·m','Input torque · N·m',1,12,1,6)],'gears');
add('thermal',['La energía que se pierde por rozamiento aparece como calor. La temperatura sube si entra calor más rápido de lo que sale.','Energy lost through friction becomes heat. Temperature rises when heat enters faster than it leaves.'],['Aumenta la potencia de fricción y compara dos niveles de refrigeración. Recorre el tiempo.','Increase friction power and compare two cooling levels. Scrub through time.'],['La temperatura se aproxima a un equilibrio; más refrigeración reduce ese equilibrio. El color es un indicador de temperatura, no una predicción del aceite.','Temperature approaches an equilibrium; more cooling lowers that equilibrium. Colour is a temperature indicator, not an oil prediction.'],['Lubricar reduce desgaste y pérdidas; refrigerar transporta calor. Son funciones relacionadas pero distintas.','Lubrication reduces wear and losses; cooling carries heat away. These are related but distinct jobs.'],[c('Fricción · W','Friction · W',50,500,50,200),c('Refrigeración · W/K','Cooling · W/K',2,20,2,10)],'thermal');
add('nostart',['Para encontrar una caída de tensión hay que observar el circuito mientras circula corriente. Una batería puede medir bien en reposo y fallar bajo carga.','To find a voltage drop, observe the circuit while current flows. A battery can read well at rest and fail under load.'],['Aumenta la resistencia de masa manteniendo la misma batería. Compara tensión en motor y pérdida en cable.','Increase ground resistance with the same battery. Compare motor voltage and cable loss.'],['Parte de la tensión se pierde en la conexión. Este modelo resistivo de arranque no calcula la velocidad del motor.','Some voltage is lost across the connection. This resistive starting model does not calculate motor speed.'],['Medir caída de tensión distingue un mal contacto de una batería descargada mejor que cambiar piezas al azar.','A voltage-drop measurement separates a bad connection from a discharged battery better than random parts replacement.'],[c('Batería · V','Battery · V',8,13,.5,12),c('Resistencia de masa · Ω','Ground resistance · Ω',0,.1,.01,.01)],'circuit');
add('ohm',['La tensión es energía por carga; la corriente es carga por segundo. La resistencia limita cuánto circula para una tensión dada.','Voltage is energy per charge; current is charge per second. Resistance limits how much flows for a given voltage.'],['Duplica la tensión. Restablécela y duplica la resistencia.','Double voltage. Restore it, then double resistance.'],['Duplicar tensión duplica corriente y cuadruplica potencia en la misma resistencia. Duplicar resistencia a tensión fija reduce corriente a la mitad.','Doubling voltage doubles current and quadruples resistor power. Doubling resistance at fixed voltage halves current.'],['Una resistencia necesita soportar la potencia disipada, no solo tener el valor correcto en ohmios.','A resistor must handle dissipated power, not just have the right resistance value.'],[c('Tensión · V','Voltage · V',0,24,1,12),c('Resistencia · Ω','Resistance · Ω',100,2000,100,1000)],'circuit');
add('ac',['En alterna, la polaridad cambia. La corriente de una resistencia cambia de sentido con la tensión; su calentamiento sigue siendo positivo.','In AC, polarity reverses. Resistor current reverses with voltage; heating remains positive.'],['Recorre la onda por sus ceros y picos. Cambia la frecuencia sin cambiar el pico.','Scrub through zero crossings and peaks. Change frequency without changing the peak.'],['Más frecuencia comprime el periodo; no aumenta el valor RMS si el pico es igual. RMS compara el calentamiento con DC.','Higher frequency shortens the period; it does not raise RMS at the same peak. RMS compares heating with DC.'],['12 V de pico senoidal son 8,49 V RMS, no 12 V RMS.','A 12 V sine peak is 8.49 V RMS, not 12 V RMS.'],[c('Pico · V','Peak · V',1,24,1,12),c('Frecuencia · Hz','Frequency · Hz',10,100,10,50)],'circuit');
add('threephase',['Tres corrientes separadas 120° producen un campo que cambia de orientación de forma continua.','Three currents separated by 120° produce a field whose orientation changes continuously.'],['Pausa en distintos puntos del ciclo. Mira las tres señales y la orientación del campo.','Pause at different points of the cycle. Watch all three signals and field orientation.'],['Cuando una fase cruza cero, las otras no son cero. En un sistema equilibrado, la suma instantánea de corrientes es cero.','When one phase crosses zero, the other two are not zero. In a balanced system, instantaneous currents sum to zero.'],['El motor de inducción necesita deslizamiento para producir par: el rotor no sigue exactamente al campo.','An induction motor needs slip to produce torque: its rotor does not exactly follow the field.'],[c('Frecuencia · Hz','Frequency · Hz',10,100,10,50),c('Deslizamiento · %','Slip · %',0,10,1,4)],'motor');
add('rectifier',['El puente recarga el condensador dos veces por ciclo. Después, el regulador reduce la tensión para entregar 8 V a la carga. Necesita al menos 9 V a la entrada.','The bridge tops up the capacitor twice per cycle. Downstream, the regulator drops the excess voltage to deliver 8 V to the load. It needs at least 9 V at its input.'],['Compara 1000 Ω con 100 Ω. Recorre el valle donde la tensión filtrada cruza 9 V y observa la salida.','Compare 1000 Ω with 100 Ω. Scrub across the trough where the filtered voltage crosses 9 V and watch the output.'],['Menos resistencia exige más corriente. El condensador pierde carga más rápido entre picos. Por debajo de 9 V, la salida sigue al condensador con 1 V de caída.','Lower resistance draws more current. The capacitor loses charge faster between peaks. Below 9 V the output follows the capacitor with a 1 V drop, down to zero.'],['Aumenta la capacitancia hasta que el valle quede por encima de 9 V. La entrada aún ondula, pero la salida se mantiene en 8 V durante todo el ciclo.','Increase capacitance until the trough stays above 9 V. The input still ripples, but the output holds 8 V throughout the cycle.'],[c('Pico entrada · V','Input peak · V',1,24,1,12),c('Caída por diodo · V','Drop per diode · V',0,1,.1,.7),c('Capacitancia · µF','Capacitance · µF',0,2200,10,100),c('Resistencia de carga · Ω','Load resistance · Ω',100,2000,50,200),c('Regulador (0 = puenteado, 1 = activo)','Regulator (0 = bypass, 1 = on)',0,1,1,1)],'circuit');
add('opamp',['El operacional usa energía de su alimentación para producir una copia amplificada de la señal. La entrada no aporta la potencia de salida.','The op amp uses supply energy to make an amplified copy of a signal. The input does not supply the output power.'],['Sube la ganancia hasta que pico × ganancia supere 12 V.','Raise gain until peak × gain exceeds 12 V.'],['Los picos se recortan: pedir más ganancia ya no aumenta la salida en esos instantes. Las columnas 3D son indicadores de |V|, no piezas del chip.','Peaks clip: requesting more gain no longer increases output at those moments. The 3D columns indicate |V|; they are not chip parts.'],['La saturación de un amplificador puede parecer un sensor defectuoso. Comprueba entrada, ganancia y alimentación.','Amplifier saturation can look like a faulty sensor. Check input, gain and supply.'],[c('Pico entrada · V','Input peak · V',.5,5,.5,2),c('Ganancia','Gain',1,10,1,5)],'opamp');
add('pascal',['La presión se transmite por el líquido; la fuerza depende además del área sobre la que actúa.','Pressure is transmitted through the liquid; force also depends on the area it acts on.'],['Duplica el área de salida y recorre la misma carrera de entrada.','Double output area and scrub the same input stroke.'],['La fuerza aumenta, pero la carrera de salida disminuye. El volumen desplazado se conserva: A₁x₁ = A₂x₂.','Force increases, but output travel decreases. Displaced volume is conserved: A₁x₁ = A₂x₂.'],['Un gato levanta mucho peso porque intercambia recorrido por fuerza; no crea trabajo.','A jack lifts a heavy weight by trading travel for force; it does not create work.'],[c('Fuerza entrada · N','Input force · N',10,100,10,20),c('Relación de áreas','Area ratio',1,6,1,4)],'press');
add('flow',['El caudal es volumen por segundo. Para avanzar un pistón hay que llenar el volumen que deja detrás.','Flow is volume per second. Advancing a piston requires filling the volume left behind it.'],['Duplica el caudal y observa cuánto avanza en el mismo tiempo. Luego aumenta el área.','Double flow and observe travel over the same time. Then increase area.'],['v = Q/A: más caudal acelera; más área ralentiza a igual caudal. La presión determina capacidad de fuerza, no la velocidad por sí sola.','v = Q/A: more flow speeds motion; more area slows it at the same flow. Pressure determines force capacity, not speed by itself.'],['Para un cilindro lento, mide caudal útil antes de aumentar la presión.','For a slow cylinder, measure useful flow before raising pressure.'],[c('Caudal · L/min','Flow · L/min',1,12,1,6),c('Área · cm²','Area · cm²',10,60,10,20)],'hydraulic');
add('power',['Presión y caudal juntos transportan potencia. Una caída de presión con flujo transforma parte de ella en calor.','Pressure and flow together carry power. A pressure drop with flow converts some of it into heat.'],['Mantén el caudal y aumenta la caída de presión en una restricción.','Keep flow fixed and increase restriction pressure drop.'],['La pérdida Δp × Q aumenta, aunque el cilindro conserve velocidad en esta fuente ideal de caudal.','Loss Δp × Q increases, even though cylinder speed stays constant with this ideal flow source.'],['Una válvula estranguladora puede controlar velocidad a costa de calentar el aceite.','A throttle valve can control speed at the cost of heating the oil.'],[c('Caudal · L/min','Flow · L/min',1,12,1,6),c('Caída de presión · bar','Pressure drop · bar',0,100,5,20)],'hydraulic');
add('relief',['La válvula de alivio abre un camino al tanque cuando la presión supera el ajuste.','The relief valve opens a route to the tank when pressure exceeds its setting.'],['Sube la presión desde debajo del ajuste hasta superarlo. Sigue el flujo que regresa al tanque.','Raise pressure from below the setting to above it. Follow flow returning to the tank.'],['Al abrir, una parte del caudal deja de ir al cilindro. La energía del retorno a presión se disipa en calor.','As it opens, some flow no longer reaches the cylinder. Pressurised return energy dissipates as heat.'],['No es un acelerador del cilindro: subir el ajuste no repara una fuga ni crea caudal.','It is not a cylinder accelerator: raising the setting does not repair a leak or create flow.'],[c('Presión impuesta · bar','Imposed pressure · bar',10,120,5,50),c('Ajuste · bar','Setting · bar',20,100,5,60)],'relief');
add('hydrodiagnosis',['El caudal de la bomba no es siempre el caudal que mueve el pistón. Parte puede escapar por una fuga.','Pump flow is not always the flow moving the piston. Some may escape through a leak.'],['Mantén 6 L/min de entrada y aumenta la fuga de 0 a 3 L/min.','Keep inlet flow at 6 L/min and raise leakage from 0 to 3 L/min.'],['La velocidad se reduce a la mitad. Una lectura de presión aislada no localiza esa pérdida de caudal.','Speed halves. A pressure reading alone does not locate that lost flow.'],['Compara caudal de entrada, velocidad y retorno para separar fuga interna de alimentación insuficiente.','Compare inlet flow, speed and return to separate internal leakage from insufficient supply.'],[c('Entrada · L/min','Inlet · L/min',3,12,1,6),c('Fuga · L/min','Leak · L/min',0,3,.5,0)],'hydraulic');
add('air',['El aire puede comprimirse: las mismas moléculas ocupan menos volumen y chocan más a menudo con las paredes.','Air can compress: the same molecules occupy less volume and hit the walls more often.'],['Reduce a la mitad el volumen de una muestra sellada a temperatura constante.','Halve the volume of a sealed sample at constant temperature.'],['La presión absoluta se duplica. El manómetro resta aproximadamente 1 bar de atmósfera: 2 bar absolutos son aproximadamente 1 bar manométrico.','Absolute pressure doubles. A gauge subtracts approximately 1 bar atmospheric pressure: 2 bar absolute is approximately 1 bar gauge.'],['Para usar pV = constante necesitas presión absoluta, no manométrica.','To use pV = constant you need absolute pressure, not gauge pressure.'],[c('Volumen · L','Volume · L',.25,2,.25,1)],'gas');
add('airchain',['El compresor aporta aire; el depósito amortigua variaciones; filtro y regulador preparan el suministro.','The compressor supplies air; the receiver buffers variations; filter and regulator prepare the supply.'],['Reduce la presión disponible por debajo de la consigna del regulador.','Reduce available pressure below the regulator setting.'],['El regulador no puede crear presión. Un filtro obstruido produce caída mientras hay flujo, aunque en reposo el manómetro parezca normal.','A regulator cannot create pressure. A clogged filter produces a drop while air flows even if the resting gauge looks normal.'],['Mide suministro durante la carrera, no solo con la máquina quieta.','Measure supply during the stroke, not only while the machine is stationary.'],[c('Suministro · bar','Supply · bar',1,8,1,6),c('Consigna · bar','Setting · bar',1,8,1,4),c('Caída con flujo · bar','Flowing pressure drop · bar',0,2,.5,0)],'pneumatic');
add('valve52',['Una válvula 5/2 conecta cinco puertos en dos posiciones: alimenta una cámara y deja escapar la otra.','A 5/2 valve connects five ports in two positions: it supplies one chamber and exhausts the other.'],['Recorre avance y retorno. Sigue P→A y B→escape; después P→B y A→escape.','Scrub extension and retraction. Follow P→A and B→exhaust, then P→B and A→exhaust.'],['La cámara que se vacía necesita salida a la atmósfera. Bloquearla genera contrapresión.','The emptying chamber needs a route to atmosphere. Blocking it creates backpressure.'],['Los escapes terminan en silenciadores, no en el depósito de aire comprimido.','Exhausts end in silencers, not in the compressed-air receiver.'],[c('Presión · bar','Pressure · bar',1,8,1,4)],'pneumatic');
add('cylinderforce',['El vástago ocupa parte del área de una cara. Con la misma presión, el retorno ofrece menos fuerza que el avance.','The rod occupies part of one piston face. At equal pressure, retraction provides less force than extension.'],['Compara avance y retorno a la misma presión. Añade contrapresión en el escape.','Compare extension and retraction at the same pressure. Add exhaust backpressure.'],['Hay que restar la fuerza de la cámara opuesta: F = pA − p opuesta × A opuesta.','Subtract force from the opposite chamber: F = pA − opposing pressure × opposing area.'],['Elige el cilindro por fuerza neta, rozamiento y margen de carga; no solo por presión de suministro.','Choose a cylinder using net force, friction and load margin, not supply pressure alone.'],[c('Suministro · bar','Supply · bar',1,8,1,4),c('Contrapresión · bar','Backpressure · bar',0,3,.5,0)],'pneumatic');
add('pneudiagnosis',['Restringir el escape deja presión al otro lado del pistón. El cilindro puede tener suministro correcto y poca fuerza neta.','Restricting exhaust leaves pressure on the opposite side of the piston. A cylinder can have correct supply and little net force.'],['Sube la contrapresión con suministro fijo. Compara ambas cámaras, no solo el regulador.','Raise backpressure at fixed supply. Compare both chambers, not just the regulator.'],['La fuerza disponible cae. Este banco muestra la ruta y el balance de fuerzas; la velocidad real necesita un modelo de caudal compresible.','Available force falls. This bench shows paths and force balance; real speed requires a compressible-flow model.'],['Un silenciador obstruido, un tubo estrangulado y falta de suministro pueden parecer el mismo “cilindro lento”. Las mediciones los separan.','A clogged silencer, pinched tube and insufficient supply can all look like a “slow cylinder”. Measurements separate them.'],[c('Suministro · bar','Supply · bar',1,8,1,4),c('Contrapresión · bar','Backpressure · bar',0,3,.5,0)],'pneumatic');
